{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.siraj_collection AS WITH params AS ( SELECT DATEADD(DAY, -1, CURRENT_DATE()) AS as_of_date, DATE_TRUNC(\'month\', DATEADD(DAY, -1, CURRENT_DATE())) AS as_of_month, DAY(DATEADD(DAY, -1, CURRENT_DATE())) AS cutoff_day ), main AS ( SELECT _airbyte_data:\"Channel Ledger\"::STRING AS channel_ledger, _airbyte_data:\"Entity\"::STRING AS entity, _airbyte_data:\"Facility\"::STRING AS facility, NULLIF( _airbyte_data:\"GRN Price Without Tax\"::STRING, \'\' )::FLOAT AS grn_price_without_tax, NULLIF( _airbyte_data:\"MRP\"::STRING, \'\' )::FLOAT AS mrp, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP AS original_created_date, TRY_TO_DATE( _airbyte_data:\"Original_Invoice_Date\"::VARCHAR, \'DD-MM-YYYY\' ) AS original_invoice_date, _airbyte_data:\"Product SKU Code\"::STRING AS product_sku_code, NULLIF( _airbyte_data:\"Quantity\"::STRING, \'\' )::INTEGER AS quantity, _airbyte_data:\"Sale Order Number\"::STRING AS sale_order_number, NULLIF( _airbyte_data:\"Sales\"::STRING, \'\' )::FLOAT AS sales, NULLIF( _airbyte_data:\"Total\"::STRING, \'\' )::FLOAT AS total FROM snitch_db.maplemonk._AIRBYTE_RAW_UC_AARYAN_GET_TALLY_GST_REPORT QUALIFY ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:\"Sale Order Number\"::STRING, _airbyte_data:\"Product SKU Code\"::STRING, _airbyte_data:\"Warehouse Name\"::STRING, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP ORDER BY _airbyte_data:\"Ingested At\"::TIMESTAMP DESC ) = 1 UNION ALL SELECT channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, TO_DATE(Original_Invoice_Date, \'DD-MM-YYYY\') AS original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total FROM snitch_db.MAPLEMONK.MIS_JAN206_MAY20260502 UNION ALL SELECT GET(VARIANT_COL, \'Channel Ledger\')::STRING AS channel_ledger, GET(VARIANT_COL, \'Entity\')::STRING AS entity, GET(VARIANT_COL, \'Facility\')::STRING AS facility, GET(VARIANT_COL, \'GRN Price Without Tax\')::FLOAT AS grn_price_without_tax, GET(VARIANT_COL, \'MRP\')::FLOAT AS mrp, GET(VARIANT_COL, \'Original_Created_Date\')::TIMESTAMP AS original_created_date, TO_DATE( GET(VARIANT_COL, \'Original_Invoice_Date\')::VARCHAR, \'DD-MM-YYYY\' ) AS original_invoice_date, GET(VARIANT_COL, \'Product SKU Code\')::STRING AS product_sku_code, GET(VARIANT_COL, \'Quantity\')::INT AS quantity, GET(VARIANT_COL, \'Sale Order Number\')::STRING AS sale_order_number, GET(VARIANT_COL, \'Sales\')::FLOAT AS sales, GET(VARIANT_COL, \'Total\')::FLOAT AS total FROM snitch_db.MAPLEMONK.mis_feb_20260504 UNION ALL SELECT channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, TO_DATE(Original_Invoice_Date, \'DD-MM-YYYY\') AS original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total FROM snitch_db.MAPLEMONK.MIS_20260428 ), cost_price_map AS ( SELECT sku_group, cost_price, category FROM SNITCH_DB.MAPLEMONK.base_product QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY cost_price DESC ) = 1 ), cat_mp AS ( SELECT CASE WHEN LEFT(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' THEN SPLIT_PART(UPPER(TRIM(SKUGROUP)), \'-\', 0) ELSE UPPER(TRIM(SKUGROUP)) END AS sku_group, CASE WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category IN ( \'PYJAMAS\', \'Night Suit & Pyjamas\', \'Joggers & Trackpants\', \'Trackpants\', \'JOGGERS\' ) THEN \'Joggers & Trackpants\' WHEN category = \'Shirt\' THEN \'Shirts\' WHEN category = \'Sweater\' THEN \'Sweaters\' WHEN category = \'T-Shirt\' THEN \'T-Shirts\' WHEN category IN (\'Trouser\', \'Chinos\') THEN \'Trousers\' ELSE category END AS category FROM snitch_db.maplemonk.uc_final_item_master QUALIFY ROW_NUMBER() OVER ( PARTITION BY CASE WHEN LEFT(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' THEN SPLIT_PART(UPPER(TRIM(SKUGROUP)), \'-\', 0) ELSE UPPER(TRIM(SKUGROUP)) END ORDER BY CASE WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category IN ( \'PYJAMAS\', \'Night Suit & Pyjamas\', \'Joggers & Trackpants\', \'Trackpants\', \'JOGGERS\' ) THEN \'Joggers & Trackpants\' WHEN category = \'Shirt\' THEN \'Shirts\' WHEN category = \'Sweater\' THEN \'Sweaters\' WHEN category = \'T-Shirt\' THEN \'T-Shirts\' WHEN category IN (\'Trouser\', \'Chinos\') THEN \'Trousers\' ELSE category END ASC ) = 1 ), shopify_gross AS ( SELECT original_invoice_date AS date, sale_order_number AS order_name, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX( \'-\', REVERSE(product_sku_code) ) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, \'Shopify\' AS channel, SUM(quantity)::INT AS quantity, SUM(sales)::INT AS sales, SUM(mrp * quantity)::INT AS mrp, SUM(total)::INT AS total, SUM( COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( grn_price_without_tax, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) * COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( quantity, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) )::INT AS cost_price FROM main WHERE channel_ledger = \'Snitch\' AND entity = \'NEW_INVOICE\' GROUP BY 1, 2, 3, 4 ), shopify_net AS ( SELECT \"Display Order Number\" AS order_name, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(\"Product SKU Code\"), CHARINDEX( \'-\', REVERSE(\"Product SKU Code\") ) + 1, LEN(\"Product SKU Code\") ) ) ) ) AS sku_group, SUM(QTY) AS return_qty FROM snitch_db.maplemonk.uc_get_tally_return_gst_report WHERE \"Channel Ledger\" = \'Snitch\' GROUP BY 1, 2 ), shopify AS ( SELECT a.*, CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END AS return_qty, CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN \'false\' ELSE \'true\' END AS flag, sales * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_sales, mrp * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_mrp, total * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_total, cost_price * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_cost_price FROM shopify_gross a LEFT JOIN shopify_net b ON a.order_name = b.order_name AND a.sku_group = b.sku_group ), shopify_main AS ( SELECT a.date, a.sku_group, b.category, a.channel, SUM(quantity) AS quantity, SUM(quantity - return_qty) AS net_quantity, SUM(total) AS sales, SUM(net_total) AS net_sales, SUM(mrp - total) AS discount, SUM(net_mrp - net_total) AS net_discount, SUM(a.cost_price) AS cost_price, SUM(net_cost_price) AS net_cost_price FROM shopify a LEFT JOIN cost_price_map b ON a.sku_group = b.sku_group GROUP BY 1, 2, 3, 4 ), mp_gross AS ( SELECT original_invoice_date AS date, sale_order_number AS order_name, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX( \'-\', REVERSE(product_sku_code) ) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, CASE WHEN channel_ledger IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\' ) THEN \'MP_Ajio\' WHEN channel_ledger IN ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\' ) THEN \'MP_Amazon\' WHEN channel_ledger IN ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) THEN \'MP_Myntra_PPMP\' WHEN channel_ledger IN ( \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) THEN \'MP_Nykaa\' ELSE \'others\' END AS channel, SUM(quantity) AS quantity, SUM( CASE WHEN channel_ledger IN ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) THEN total WHEN channel_ledger IN ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) AND original_invoice_date >= \'2026-03-26\' THEN total + quantity * avg_cat_charges WHEN channel_ledger IN ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) THEN total WHEN channel_ledger IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\' ) THEN (total / 0.68)::INT ELSE sales END )::INT AS sales, SUM( COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( mrp, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) * COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( quantity, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) ) AS mrp, SUM( COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( grn_price_without_tax, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) * COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( quantity, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) ) AS cp FROM main a LEFT JOIN cost_price_map b ON TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(a.product_sku_code), CHARINDEX( \'-\', REVERSE(a.product_sku_code) ) + 1, LEN(a.product_sku_code) ) ) ) ) = b.sku_group LEFT JOIN snitch_db.maplemonk.AVG_GT_CHARGES c ON b.category = c.category WHERE channel_ledger IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) GROUP BY 1, 2, 3, 4 ), mp_return AS ( SELECT \"Display Order Number\" AS order_name, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(\"Product SKU Code\"), CHARINDEX( \'-\', REVERSE(\"Product SKU Code\") ) + 1, LEN(\"Product SKU Code\") ) ) ) ) AS sku_group, SUM(QTY) AS return_qty FROM snitch_db.maplemonk.uc_get_tally_return_gst_report WHERE \"Channel Ledger\" IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) GROUP BY 1, 2 ), mp_main_pre AS ( SELECT a.*, CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END AS return_qty, CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN \'false\' ELSE \'true\' END AS flag, sales * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_sales, mrp * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_mrp, cp * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_cp FROM mp_gross a LEFT JOIN mp_return b ON a.order_name = b.order_name AND a.sku_group = b.sku_group ), mp_main AS ( SELECT a.date, a.sku_group, b.category, a.channel, SUM(quantity) AS quantity, SUM(quantity - return_qty) AS net_quantity, SUM(sales) AS sales, SUM(net_sales) AS net_sales, SUM(mrp - sales) AS discount, SUM(net_mrp - net_sales) AS net_discount, SUM(cp) AS cost_price, SUM(net_cp) AS net_cost_price FROM mp_main_pre a LEFT JOIN cost_price_map b ON a.sku_group = b.sku_group GROUP BY 1, 2, 3, 4 ), offline_pre AS ( SELECT b.order_date::DATE AS date, COALESCE(cp.category, \'others\') AS category, \'Store\' AS channel, b.sku_group, CASE WHEN marketplace_mapped IN ( \'SNITCH - WH - B2B\', \'SNITCH - SNITCH X\', \'SNITCH - WH - M P\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - U.P\', \'SNITCH - WH - NORTH\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - EMIZA\', \'SNITCH - WH - YELHANKA 2\' ) OR b.sku_group LIKE \'cb%\' OR doc_prefix IN (\'OMS\', \'QCOM\') THEN 1 ELSE 0 END AS filters, SUM(b.shipping_quantity)::INT AS quantity, SUM(b.shipping_quantity)::INT AS net_quantity, SUM(b.selling_price)::INT AS sales, SUM(b.selling_price)::INT AS net_sales, SUM(discount)::INT AS discount, SUM(discount)::INT AS net_discount, SUM( cp.cost_price * b.shipping_quantity )::INT AS cost_price, SUM( cp.cost_price * b.shipping_quantity )::INT AS net_cost_price FROM snitch_db.maplemonk.store_fact_items_offline b LEFT JOIN cost_price_map cp ON b.sku_group = cp.sku_group WHERE COALESCE(cp.category, \'others\') <> \'others\' GROUP BY 1, 2, 3, 4, 5 ), offline_main AS ( SELECT date, sku_group, category, channel, quantity, net_quantity, sales, net_sales, discount, net_discount, cost_price, net_cost_price FROM offline_pre WHERE filters = 0 ), myntra_sor AS ( SELECT TO_DATE(order_created_date, \'YYYYMMDD\') AS date, UPPER(TRIM(a.style)) AS sku_group, b.category, \'MP_myntra_SOR\' AS channel, SUM(sales) AS quantity, SUM(sales) AS net_quantity, SUM(REPLACE(revenue, \',\', \'\')) AS sales, SUM(REPLACE(revenue, \',\', \'\')) AS net_sales, SUM( REPLACE(\"MRP Sales\", \',\', \'\') - REPLACE(revenue, \',\', \'\') ) AS discount, SUM( REPLACE(\"MRP Sales\", \',\', \'\') - REPLACE(revenue, \',\', \'\') ) AS net_discount, SUM(REPLACE(cogs_qty, \',\', \'\')) AS cost_price, SUM(REPLACE(cogs_qty, \',\', \'\')) AS net_cost_price FROM snitch_db.maplemonk.S3_MYNTRA_B2B_GP a LEFT JOIN cat_mp b ON UPPER(TRIM(a.style)) = b.sku_group GROUP BY 1, 2, 3, 4 ), flipkart_sor AS ( SELECT TO_DATE(order_date_key, \'YYYYMMDD\') AS date, UPPER(TRIM(a.style)) AS sku_group, category, \'MP_flipkart_SOR\' AS channel, SUM(REPLACE(units, \',\', \'\')) AS quantity, SUM(REPLACE(units, \',\', \'\')) AS net_quantity, SUM(REPLACE(SP_Qty, \',\', \'\')) AS sales, SUM(REPLACE(SP_Qty, \',\', \'\')) AS net_sales, SUM( REPLACE(\"MRP Rev\", \',\', \'\') - REPLACE(SP_QTY_EXCL_GST, \',\', \'\') ) AS discount, SUM( REPLACE(\"MRP Rev\", \',\', \'\') - REPLACE(SP_QTY_EXCL_GST, \',\', \'\') ) AS net_discount, SUM(REPLACE(COGS_UNITS, \',\', \'\')) AS cost_price, SUM(REPLACE(COGS_UNITS, \',\', \'\')) AS net_cost_price FROM snitch_db.maplemonk.S3_Flipkart_B2B_GP a LEFT JOIN cat_mp b ON UPPER(TRIM(a.STYLE)) = b.sku_group GROUP BY 1, 2, 3, 4 ), slikk AS ( SELECT TO_DATE(order_date, \'DD-MM-YYYY\') AS date, UPPER(TRIM(a.\"Style \")) AS sku_group, category, \'MP_slikk\' AS channel, SUM(total_quantity) AS quantity, SUM(total_quantity) AS net_quantity, SUM(total_amount) AS sales, SUM(total_amount) AS net_sales, SUM( (mrp * total_quantity) - total_amount ) AS discount, SUM( (mrp * total_quantity) - total_amount ) AS net_discount, SUM(\"COGSxQty \") AS cost_price, SUM(\"COGSxQty \") AS net_cost_price FROM snitch_db.maplemonk.google_sheets_slikk a LEFT JOIN cat_mp b ON UPPER(TRIM(a.\"Style \")) = b.sku_group GROUP BY 1, 2, 3, 4 ), base AS ( SELECT * FROM shopify_main UNION ALL SELECT * FROM offline_main UNION ALL SELECT * FROM mp_main UNION ALL SELECT * FROM myntra_sor UNION ALL SELECT * FROM flipkart_sor UNION ALL SELECT * FROM slikk ), base_filtered AS ( SELECT b.* FROM base b JOIN params p ON 1 = 1 WHERE b.date <= p.as_of_date ), daily AS ( SELECT date, category, sku_group, channel, SUM(quantity)::NUMBER AS quantity, SUM(sales)::NUMBER AS sales, SUM(discount)::NUMBER AS discount, SUM(cost_price)::NUMBER AS cost_price, SUM(net_quantity)::NUMBER AS net_quantity, SUM(net_sales)::NUMBER AS net_sales, SUM(net_discount)::NUMBER AS net_discount, SUM(net_cost_price)::NUMBER AS net_cost_price FROM base_filtered GROUP BY 1, 2, 3, 4 ), daily_final AS ( SELECT d.date, d.category, d.channel, d.sku_group, d.sales, d.quantity, d.discount, d.cost_price, d.net_sales, d.net_quantity, d.net_discount, d.net_cost_price, LAG(d.sales) OVER ( PARTITION BY d.category, d.channel ORDER BY d.date ) AS prev_day_sales, CASE WHEN LAG(d.sales) OVER ( PARTITION BY d.category, d.channel ORDER BY d.date ) = 0 THEN NULL ELSE ( d.sales - LAG(d.sales) OVER ( PARTITION BY d.category, d.channel ORDER BY d.date ) ) / LAG(d.sales) OVER ( PARTITION BY d.category, d.channel ORDER BY d.date ) END AS dod_growth FROM daily d ), img AS ( WITH images AS ( SELECT UPPER( TRIM( CASE WHEN variant.value:sku::STRING ILIKE \'4C%\' OR variant.value:sku::STRING ILIKE \'MP%\' THEN REGEXP_SUBSTR( variant.value:sku::STRING, \'^[^-]+-[^-]+-[^-]+\' ) ELSE REGEXP_SUBSTR( variant.value:sku::STRING, \'^[^-]+-[^-]+\' ) END ) ) AS sku_group, image.value:preview:image:url::STRING AS image_url, image.index AS image_index FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN( INPUT => PARSE_JSON(t.media) ) AS image, LATERAL FLATTEN( INPUT => PARSE_JSON(t.variants) ) AS variant WHERE image.value:mediaContentType::STRING = \'IMAGE\' ) SELECT sku_group, image_url FROM images QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY image_index ) = 1 ) SELECT df.*, CASE WHEN UPPER(TRIM(df.sku_group)) IN ( \'4MST011-01\', \'4PL026-01\', \'4PL055-01\', \'4MST3252-01\', \'4MST3254-01\', \'4MST3255-01\', \'4PL027-01\', \'4PL028-01\', \'4PL042-01\' ) THEN \'Street FC\' WHEN UPPER(TRIM(df.sku_group)) IN ( \'4MBGST1252-01\', \'4MBGST1253-01\', \'4MBGST1254-01\', \'4BPL007-01\', \'4BPL014-01\', \'4BPL015-01\' ) THEN \'Street FC Plus\' ELSE \'Siraj\' END AS collection_identifier, img.image_url FROM daily_final df LEFT JOIN img USING (sku_group) WHERE sku_group IN ( \'4RN216-01\', \'4RN217-01\', \'4RN218-01\', \'4RN219-01\', \'4RN224-01\', \'4RN222-01\', \'4RN224-02\', \'4PL122-01\', \'4PL122-02\', \'4PL124-01\', \'4PL124-02\', \'4PL127-01\', \'4TR034-01\', \'4TR034-02\', \'4TR035-01\', \'4TR035-02\', \'4RN221-01\', \'4PL123-01\', \'4PL125-01\', \'4OS019-01\', \'4OS019-02\', \'4JE093-01\', \'4JE093-02\', \'4SH018-01\', \'4JO007-01\', \'4CA004-01\', \'4OS020-01\', \'4RN223-01\', \'4RN223-02\', \'4RN223-03\', \'4SHS151-01\', \'4SHS151-02\', \'4RN220-01\', \'4SHS144-01\', \'4PL126-01\', \'4SFS150-01\', \'4SFS150-02\', \'4SHS143-01\', \'4SHS145-01\', \'4SHS147-01\', \'4SHS147-02\', \'4SHS148-01\', \'4SHS149-01\', \'4SHS175-01\', \'4MST011-01\', \'4PL026-01\', \'4PL055-01\', \'4MST3252-01\', \'4MST3254-01\', \'4MST3255-01\', \'4PL027-01\', \'4PL028-01\', \'4PL042-01\', \'4MBGST1252-01\', \'4MBGST1253-01\', \'4MBGST1254-01\', \'4BPL007-01\', \'4BPL014-01\', \'4BPL015-01\' ); ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.siraj_collection_overall AS WITH params AS ( SELECT DATEADD(DAY, -1, CURRENT_DATE()) AS as_of_date, DATE_TRUNC(\'month\', DATEADD(DAY, -1, CURRENT_DATE())) AS as_of_month, DAY(DATEADD(DAY, -1, CURRENT_DATE())) AS cutoff_day ), main AS ( SELECT _airbyte_data:\"Channel Ledger\"::STRING AS channel_ledger, _airbyte_data:\"Entity\"::STRING AS entity, _airbyte_data:\"Facility\"::STRING AS facility, NULLIF( _airbyte_data:\"GRN Price Without Tax\"::STRING, \'\' )::FLOAT AS grn_price_without_tax, NULLIF( _airbyte_data:\"MRP\"::STRING, \'\' )::FLOAT AS mrp, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP AS original_created_date, TRY_TO_DATE( _airbyte_data:\"Original_Invoice_Date\"::VARCHAR, \'DD-MM-YYYY\' ) AS original_invoice_date, _airbyte_data:\"Product SKU Code\"::STRING AS product_sku_code, NULLIF( _airbyte_data:\"Quantity\"::STRING, \'\' )::INTEGER AS quantity, _airbyte_data:\"Sale Order Number\"::STRING AS sale_order_number, NULLIF( _airbyte_data:\"Sales\"::STRING, \'\' )::FLOAT AS sales, NULLIF( _airbyte_data:\"Total\"::STRING, \'\' )::FLOAT AS total FROM snitch_db.maplemonk._AIRBYTE_RAW_UC_AARYAN_GET_TALLY_GST_REPORT QUALIFY ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:\"Sale Order Number\"::STRING, _airbyte_data:\"Product SKU Code\"::STRING, _airbyte_data:\"Warehouse Name\"::STRING, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP ORDER BY _airbyte_data:\"Ingested At\"::TIMESTAMP DESC ) = 1 UNION ALL SELECT channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, TO_DATE(Original_Invoice_Date, \'DD-MM-YYYY\') AS original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total FROM snitch_db.MAPLEMONK.MIS_JAN206_MAY20260502 UNION ALL SELECT GET(VARIANT_COL, \'Channel Ledger\')::STRING AS channel_ledger, GET(VARIANT_COL, \'Entity\')::STRING AS entity, GET(VARIANT_COL, \'Facility\')::STRING AS facility, GET(VARIANT_COL, \'GRN Price Without Tax\')::FLOAT AS grn_price_without_tax, GET(VARIANT_COL, \'MRP\')::FLOAT AS mrp, GET(VARIANT_COL, \'Original_Created_Date\')::TIMESTAMP AS original_created_date, TO_DATE( GET(VARIANT_COL, \'Original_Invoice_Date\')::VARCHAR, \'DD-MM-YYYY\' ) AS original_invoice_date, GET(VARIANT_COL, \'Product SKU Code\')::STRING AS product_sku_code, GET(VARIANT_COL, \'Quantity\')::INT AS quantity, GET(VARIANT_COL, \'Sale Order Number\')::STRING AS sale_order_number, GET(VARIANT_COL, \'Sales\')::FLOAT AS sales, GET(VARIANT_COL, \'Total\')::FLOAT AS total FROM snitch_db.MAPLEMONK.mis_feb_20260504 UNION ALL SELECT channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, TO_DATE(Original_Invoice_Date, \'DD-MM-YYYY\') AS original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total FROM snitch_db.MAPLEMONK.MIS_20260428 ), cost_price_map AS ( SELECT sku_group, cost_price, category FROM SNITCH_DB.MAPLEMONK.base_product QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY cost_price DESC ) = 1 ), cat_mp AS ( SELECT CASE WHEN LEFT(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' THEN SPLIT_PART(UPPER(TRIM(SKUGROUP)), \'-\', 0) ELSE UPPER(TRIM(SKUGROUP)) END AS sku_group, CASE WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category IN ( \'PYJAMAS\', \'Night Suit & Pyjamas\', \'Joggers & Trackpants\', \'Trackpants\', \'JOGGERS\' ) THEN \'Joggers & Trackpants\' WHEN category = \'Shirt\' THEN \'Shirts\' WHEN category = \'Sweater\' THEN \'Sweaters\' WHEN category = \'T-Shirt\' THEN \'T-Shirts\' WHEN category IN (\'Trouser\', \'Chinos\') THEN \'Trousers\' ELSE category END AS category FROM snitch_db.maplemonk.uc_final_item_master QUALIFY ROW_NUMBER() OVER ( PARTITION BY CASE WHEN LEFT(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' THEN SPLIT_PART(UPPER(TRIM(SKUGROUP)), \'-\', 0) ELSE UPPER(TRIM(SKUGROUP)) END ORDER BY CASE WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category = \'Jacket\' THEN \'Jackets\' WHEN category IN ( \'PYJAMAS\', \'Night Suit & Pyjamas\', \'Joggers & Trackpants\', \'Trackpants\', \'JOGGERS\' ) THEN \'Joggers & Trackpants\' WHEN category = \'Shirt\' THEN \'Shirts\' WHEN category = \'Sweater\' THEN \'Sweaters\' WHEN category = \'T-Shirt\' THEN \'T-Shirts\' WHEN category IN (\'Trouser\', \'Chinos\') THEN \'Trousers\' ELSE category END ASC ) = 1 ), shopify_gross AS ( SELECT original_invoice_date AS date, sale_order_number AS order_name, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX( \'-\', REVERSE(product_sku_code) ) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, \'Shopify\' AS channel, SUM(quantity)::INT AS quantity, SUM(sales)::INT AS sales, SUM(mrp * quantity)::INT AS mrp, SUM(total)::INT AS total, SUM( COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( grn_price_without_tax, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) * COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( quantity, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) )::INT AS cost_price FROM main WHERE channel_ledger = \'Snitch\' AND entity = \'NEW_INVOICE\' GROUP BY 1, 2, 3, 4 ), shopify_net AS ( SELECT \"Display Order Number\" AS order_name, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(\"Product SKU Code\"), CHARINDEX( \'-\', REVERSE(\"Product SKU Code\") ) + 1, LEN(\"Product SKU Code\") ) ) ) ) AS sku_group, SUM(QTY) AS return_qty FROM snitch_db.maplemonk.uc_get_tally_return_gst_report WHERE \"Channel Ledger\" = \'Snitch\' GROUP BY 1, 2 ), shopify AS ( SELECT a.*, CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END AS return_qty, CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN \'false\' ELSE \'true\' END AS flag, sales * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_sales, mrp * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_mrp, total * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_total, cost_price * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_cost_price FROM shopify_gross a LEFT JOIN shopify_net b ON a.order_name = b.order_name AND a.sku_group = b.sku_group ), shopify_main AS ( SELECT a.date, a.sku_group, b.category, a.channel, SUM(quantity) AS quantity, SUM(quantity - return_qty) AS net_quantity, SUM(total) AS sales, SUM(net_total) AS net_sales, SUM(mrp - total) AS discount, SUM(net_mrp - net_total) AS net_discount, SUM(a.cost_price) AS cost_price, SUM(net_cost_price) AS net_cost_price FROM shopify a LEFT JOIN cost_price_map b ON a.sku_group = b.sku_group GROUP BY 1, 2, 3, 4 ), mp_gross AS ( SELECT original_invoice_date AS date, sale_order_number AS order_name, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX( \'-\', REVERSE(product_sku_code) ) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, CASE WHEN channel_ledger IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\' ) THEN \'MP_Ajio\' WHEN channel_ledger IN ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\' ) THEN \'MP_Amazon\' WHEN channel_ledger IN ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) THEN \'MP_Myntra_PPMP\' WHEN channel_ledger IN ( \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) THEN \'MP_Nykaa\' ELSE \'others\' END AS channel, SUM(quantity) AS quantity, SUM( CASE WHEN channel_ledger IN ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) THEN total WHEN channel_ledger IN ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) AND original_invoice_date >= \'2026-03-26\' THEN total + quantity * avg_cat_charges WHEN channel_ledger IN ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) THEN total WHEN channel_ledger IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\' ) THEN (total / 0.68)::INT ELSE sales END )::INT AS sales, SUM( COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( mrp, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) * COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( quantity, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) ) AS mrp, SUM( COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( grn_price_without_tax, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) * COALESCE( TRY_TO_NUMBER( NULLIF( REGEXP_REPLACE( quantity, \'[^0-9.-]\', \'\' ), \'\' ) ), 0 ) ) AS cp FROM main a LEFT JOIN cost_price_map b ON TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(a.product_sku_code), CHARINDEX( \'-\', REVERSE(a.product_sku_code) ) + 1, LEN(a.product_sku_code) ) ) ) ) = b.sku_group LEFT JOIN snitch_db.maplemonk.AVG_GT_CHARGES c ON b.category = c.category WHERE channel_ledger IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) GROUP BY 1, 2, 3, 4 ), mp_return AS ( SELECT \"Display Order Number\" AS order_name, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(\"Product SKU Code\"), CHARINDEX( \'-\', REVERSE(\"Product SKU Code\") ) + 1, LEN(\"Product SKU Code\") ) ) ) ) AS sku_group, SUM(QTY) AS return_qty FROM snitch_db.maplemonk.uc_get_tally_return_gst_report WHERE \"Channel Ledger\" IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) GROUP BY 1, 2 ), mp_main_pre AS ( SELECT a.*, CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END AS return_qty, CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN \'false\' ELSE \'true\' END AS flag, sales * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_sales, mrp * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_mrp, cp * ( ( quantity - CASE WHEN IFNULL(b.return_qty, 0) > quantity THEN quantity ELSE IFNULL(b.return_qty, 0) END ) / quantity ) AS net_cp FROM mp_gross a LEFT JOIN mp_return b ON a.order_name = b.order_name AND a.sku_group = b.sku_group ), mp_main AS ( SELECT a.date, a.sku_group, b.category, a.channel, SUM(quantity) AS quantity, SUM(quantity - return_qty) AS net_quantity, SUM(sales) AS sales, SUM(net_sales) AS net_sales, SUM(mrp - sales) AS discount, SUM(net_mrp - net_sales) AS net_discount, SUM(cp) AS cost_price, SUM(net_cp) AS net_cost_price FROM mp_main_pre a LEFT JOIN cost_price_map b ON a.sku_group = b.sku_group GROUP BY 1, 2, 3, 4 ), offline_pre AS ( SELECT b.order_date::DATE AS date, COALESCE(cp.category, \'others\') AS category, \'Store\' AS channel, b.sku_group, CASE WHEN marketplace_mapped IN ( \'SNITCH - WH - B2B\', \'SNITCH - SNITCH X\', \'SNITCH - WH - M P\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - U.P\', \'SNITCH - WH - NORTH\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - EMIZA\', \'SNITCH - WH - YELHANKA 2\' ) OR b.sku_group LIKE \'cb%\' OR doc_prefix IN (\'OMS\', \'QCOM\') THEN 1 ELSE 0 END AS filters, SUM(b.shipping_quantity)::INT AS quantity, SUM(b.shipping_quantity)::INT AS net_quantity, SUM(b.selling_price)::INT AS sales, SUM(b.selling_price)::INT AS net_sales, SUM(discount)::INT AS discount, SUM(discount)::INT AS net_discount, SUM( cp.cost_price * b.shipping_quantity )::INT AS cost_price, SUM( cp.cost_price * b.shipping_quantity )::INT AS net_cost_price FROM snitch_db.maplemonk.store_fact_items_offline b LEFT JOIN cost_price_map cp ON b.sku_group = cp.sku_group WHERE COALESCE(cp.category, \'others\') <> \'others\' GROUP BY 1, 2, 3, 4, 5 ), offline_main AS ( SELECT date, sku_group, category, channel, quantity, net_quantity, sales, net_sales, discount, net_discount, cost_price, net_cost_price FROM offline_pre WHERE filters = 0 ), myntra_sor AS ( SELECT TO_DATE(order_created_date, \'YYYYMMDD\') AS date, UPPER(TRIM(a.style)) AS sku_group, b.category, \'MP_myntra_SOR\' AS channel, SUM(sales) AS quantity, SUM(sales) AS net_quantity, SUM(REPLACE(revenue, \',\', \'\')) AS sales, SUM(REPLACE(revenue, \',\', \'\')) AS net_sales, SUM( REPLACE(\"MRP Sales\", \',\', \'\') - REPLACE(revenue, \',\', \'\') ) AS discount, SUM( REPLACE(\"MRP Sales\", \',\', \'\') - REPLACE(revenue, \',\', \'\') ) AS net_discount, SUM(REPLACE(cogs_qty, \',\', \'\')) AS cost_price, SUM(REPLACE(cogs_qty, \',\', \'\')) AS net_cost_price FROM snitch_db.maplemonk.S3_MYNTRA_B2B_GP a LEFT JOIN cat_mp b ON UPPER(TRIM(a.style)) = b.sku_group GROUP BY 1, 2, 3, 4 ), flipkart_sor AS ( SELECT TO_DATE(order_date_key, \'YYYYMMDD\') AS date, UPPER(TRIM(a.style)) AS sku_group, category, \'MP_flipkart_SOR\' AS channel, SUM(REPLACE(units, \',\', \'\')) AS quantity, SUM(REPLACE(units, \',\', \'\')) AS net_quantity, SUM(REPLACE(SP_Qty, \',\', \'\')) AS sales, SUM(REPLACE(SP_Qty, \',\', \'\')) AS net_sales, SUM( REPLACE(\"MRP Rev\", \',\', \'\') - REPLACE(SP_QTY_EXCL_GST, \',\', \'\') ) AS discount, SUM( REPLACE(\"MRP Rev\", \',\', \'\') - REPLACE(SP_QTY_EXCL_GST, \',\', \'\') ) AS net_discount, SUM(REPLACE(COGS_UNITS, \',\', \'\')) AS cost_price, SUM(REPLACE(COGS_UNITS, \',\', \'\')) AS net_cost_price FROM snitch_db.maplemonk.S3_Flipkart_B2B_GP a LEFT JOIN cat_mp b ON UPPER(TRIM(a.STYLE)) = b.sku_group GROUP BY 1, 2, 3, 4 ), slikk AS ( SELECT TO_DATE(order_date, \'DD-MM-YYYY\') AS date, UPPER(TRIM(a.\"Style \")) AS sku_group, category, \'MP_slikk\' AS channel, SUM(total_quantity) AS quantity, SUM(total_quantity) AS net_quantity, SUM(total_amount) AS sales, SUM(total_amount) AS net_sales, SUM( (mrp * total_quantity) - total_amount ) AS discount, SUM( (mrp * total_quantity) - total_amount ) AS net_discount, SUM(\"COGSxQty \") AS cost_price, SUM(\"COGSxQty \") AS net_cost_price FROM snitch_db.maplemonk.google_sheets_slikk a LEFT JOIN cat_mp b ON UPPER(TRIM(a.\"Style \")) = b.sku_group GROUP BY 1, 2, 3, 4 ), base AS ( SELECT * FROM shopify_main UNION ALL SELECT * FROM offline_main UNION ALL SELECT * FROM mp_main UNION ALL SELECT * FROM myntra_sor UNION ALL SELECT * FROM flipkart_sor UNION ALL SELECT * FROM slikk ), live_date_map AS ( SELECT sku_group, MIN(date) AS live_date FROM base WHERE date IS NOT NULL AND quantity > 0 GROUP BY 1 ), base_filtered AS ( SELECT b.* FROM base b JOIN params p ON 1 = 1 WHERE b.date <= p.as_of_date ), l30d_sales AS ( SELECT b.sku_group, SUM(b.quantity)::NUMBER AS l30d_qty_gross, SUM(b.net_quantity)::NUMBER AS l30d_qty_net FROM base b JOIN params p ON 1 = 1 WHERE b.date > DATEADD( DAY, -30, p.as_of_date ) AND b.date <= p.as_of_date GROUP BY 1 ), daily AS ( SELECT category, sku_group, SUM(quantity)::NUMBER AS quantity, SUM(sales)::NUMBER AS sales, SUM(discount)::NUMBER AS discount, SUM(cost_price)::NUMBER AS cost_price, SUM(net_quantity)::NUMBER AS net_quantity, SUM(net_sales)::NUMBER AS net_sales, SUM(net_discount)::NUMBER AS net_discount, SUM(net_cost_price)::NUMBER AS net_cost_price FROM base_filtered GROUP BY 1, 2 ), daily_final AS ( SELECT d.category, d.sku_group, d.sales, d.quantity, d.discount, d.cost_price, d.net_sales, d.net_quantity, d.net_discount, d.net_cost_price FROM daily d ), img AS ( WITH images AS ( SELECT UPPER( TRIM( CASE WHEN variant.value:sku::STRING ILIKE \'4C%\' OR variant.value:sku::STRING ILIKE \'MP%\' THEN REGEXP_SUBSTR( variant.value:sku::STRING, \'^[^-]+-[^-]+-[^-]+\' ) ELSE REGEXP_SUBSTR( variant.value:sku::STRING, \'^[^-]+-[^-]+\' ) END ) ) AS sku_group, image.value:preview:image:url::STRING AS image_url, image.index AS image_index FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN( INPUT => PARSE_JSON(t.media) ) AS image, LATERAL FLATTEN( INPUT => PARSE_JSON(t.variants) ) AS variant WHERE image.value:mediaContentType::STRING = \'IMAGE\' ) SELECT sku_group, image_url FROM images QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY image_index ) = 1 ), inv AS ( SELECT * FROM snitch_db.maplemonk.inv_logs WHERE date = ( SELECT MAX(date) - 1 FROM snitch_db.maplemonk.inv_logs ) ) SELECT df.*, CASE WHEN UPPER(TRIM(df.sku_group)) IN ( \'4MST011-01\', \'4PL026-01\', \'4PL055-01\', \'4MST3252-01\', \'4MST3254-01\', \'4MST3255-01\', \'4PL027-01\', \'4PL028-01\', \'4PL042-01\' ) THEN \'Street FC\' WHEN UPPER(TRIM(df.sku_group)) IN ( \'4MBGST1252-01\', \'4MBGST1253-01\', \'4MBGST1254-01\', \'4BPL007-01\', \'4BPL014-01\', \'4BPL015-01\' ) THEN \'Street FC Plus\' ELSE \'Siraj\' END AS collection_identifier, img.image_url, COALESCE(total_qty, 0) AS inv, ld.live_date, CASE WHEN ld.live_date IS NULL THEN NULL ELSE DATEDIFF( DAY, ld.live_date, ( SELECT as_of_date FROM params ) ) END AS days_since_live, COALESCE( l30.l30d_qty_gross, 0 ) AS l30d_qty_gross, COALESCE( l30.l30d_qty_net, 0 ) AS l30d_qty_net FROM daily_final df LEFT JOIN img USING (sku_group) LEFT JOIN inv USING (sku_group) LEFT JOIN live_date_map ld USING (sku_group) LEFT JOIN l30d_sales l30 USING (sku_group) WHERE sku_group IN ( \'4RN216-01\', \'4RN217-01\', \'4RN218-01\', \'4RN219-01\', \'4RN224-01\', \'4RN222-01\', \'4RN224-02\', \'4PL122-01\', \'4PL122-02\', \'4PL124-01\', \'4PL124-02\', \'4PL127-01\', \'4TR034-01\', \'4TR034-02\', \'4TR035-01\', \'4TR035-02\', \'4RN221-01\', \'4PL123-01\', \'4PL125-01\', \'4OS019-01\', \'4OS019-02\', \'4JE093-01\', \'4JE093-02\', \'4SH018-01\', \'4JO007-01\', \'4CA004-01\', \'4OS020-01\', \'4RN223-01\', \'4RN223-02\', \'4RN223-03\', \'4SHS151-01\', \'4SHS151-02\', \'4RN220-01\', \'4SHS144-01\', \'4PL126-01\', \'4SFS150-01\', \'4SFS150-02\', \'4SHS143-01\', \'4SHS145-01\', \'4SHS147-01\', \'4SHS147-02\', \'4SHS148-01\', \'4SHS149-01\', \'4SHS175-01\', \'4MST011-01\', \'4PL026-01\', \'4PL055-01\', \'4MST3252-01\', \'4MST3254-01\', \'4MST3255-01\', \'4PL027-01\', \'4PL028-01\', \'4PL042-01\', \'4MBGST1252-01\', \'4MBGST1253-01\', \'4MBGST1254-01\', \'4BPL007-01\', \'4BPL014-01\', \'4BPL015-01\' );",
                    "transaction": true
                }
            ) }}
